REVERT = ['I was charged twice for one order and now my account balance is almost zero. Please hurry!', 'Tolong la cepat sikit, kena caj dua kali, duit gaji saya dah habis.', '我被扣了两次钱，现在卡里没钱了，求你们快点处理！', 'I have no money left after you charged me twice, please fix it fast!!', 'Saya dah tak ada duit, kena caj dua kali. Tolong segera!!']

def main():
    if not os.path.exists('data/data_starter_before_batch9.xlsx'):
        shutil.copy('data/data_starter.xlsx', 'data/data_starter_before_batch9.xlsx')
    wb = load_workbook('data/data_starter.xlsx')
    ws = wb['data_starter']
    reverted = 0
    for row in ws.iter_rows(min_row=2):
        if row[1].value in REVERT:
            row[3].value, row[4].value = ('medium', False)
            reverted += 1
    existing_ids = {str(r[0]) for r in ws.iter_rows(min_row=2, values_only=True) if r[0]}
    existing_msgs = {r[1] for r in ws.iter_rows(min_row=2, values_only=True) if r[1]}
    n = 51
    added = 0
    for msg, cat, urg, nh in ROWS:
        if msg in existing_msgs:
            continue
        while f'S{n:03d}' in existing_ids:
            n += 1
        ws.append([f'S{n:03d}', msg, cat, urg, nh])
        existing_ids.add(f'S{n:03d}')
        existing_msgs.add(msg)
        added += 1
    wb.save('data/data_starter.xlsx')
    print(f'added {added} rows, reverted {reverted}; sheet now has {ws.max_row - 1} rows (backup: data/data_starter_before_batch9.xlsx)')
if __name__ == '__main__':
    main()
